const Core=window.AlimentCore,DATA_BASE=window.PARC_DATA_BASE||'/scan/aliment/';
const MEMORY='vyvre-propale-parcours-assiette-v2',PREFS='vyvre-propale-parcours-prefs-v1',SCHEMA=2,ACCORD='c2-2026-10';
let s={_cases:{},allergies:[],autres_aliments:[]},mode=null,prefs={saison:true,usage:null,cuisines:[],budget:null,bio:false,cuis:false},removed=[],ry={q9s:null,q9d:false,q10p:null},keep=false,saved=null,demo=false,scores=null,pageName=window.PAGE||'questions',cleanup=()=>{},stream=null,recipeTab='plat',recipeCount=3,trendCount=4,foodFocus=0,scanBusy=false,loaded=false;
const app=document.getElementById('app'),esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes={questions:'/aliment/parcours/01-questions.html',allergies:'/aliment/parcours/01-allergies.html',besoin:'/aliment/parcours/01-besoin.html',types:'/aliment/parcours/01-envies.html',preference:'/aliment/parcours/01-preferences.html',consent:'/aliment/parcours/01-accord.html',return:'/aliment/parcours/01-retour.html',scan:'/aliment/parcours/02-scan.html',composition:'/aliment/parcours/03-traversee.html',wheel:'/aliment/parcours/03-roue.html',result:'/aliment/parcours/04-assiette.html',resultSolo:'/aliment/parcours/04-assiette-solo.html',suite:'/aliment/parcours/05-suite.html',gallery:'/scan/'};
function button(text,action,cls='primary',disabled=false){return `<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${esc(text)}</button>`}
function visual(id,caption=''){return `<div class="visual"><div class="product">${image(id)}${image(id,'reflection')}</div>${caption?`<span class="caption">${esc(caption)}</span>`:''}</div>`}
const shownPhotos=new Set();function image(id,cls='',mini=false){if(Core.get().credits&&!Core.get().credits[id])return '';shownPhotos.add(id);/* 11/10 : mini = vignette 160 px (photos/min/) pour les petites cases de la lecture en direct, la grande photo en secours */return mini?`<img src="${DATA_BASE}photos/min/${esc(id)}.png" class="${cls}" alt="" decoding="async" onerror="if(this.dataset.r){this.hidden=true}else{this.dataset.r=1;this.src='${DATA_BASE}photos/${esc(id)}.png'}">`:`<img src="${DATA_BASE}photos/${esc(id)}.png" class="${cls}" alt="" decoding="async" onerror="this.hidden=true">`}
/* 11/10 (Charles : « on n'est pas oblige de cocher plusieurs choix ») : apres chaque choix, la page passe seule a la suite
   en 2,5 s ; un nouveau choix relance le delai, tout decocher l'annule, Continuer reste cliquable. La petite jauge est sur
   le bouton Continuer (sans animation si l'appareil demande moins de mouvement : le passage reste). */
let autoT=null;function stopAuto(){clearTimeout(autoT);autoT=null;app.querySelectorAll('.compte').forEach(x=>x.classList.remove('compte'))}
function auto(action,ms=1700){stopAuto();const cb=app.querySelector(`[data-action="${action}"]`);if(cb&&!cb.disabled){cb.style.setProperty('--d',ms+'ms');void cb.offsetWidth;cb.classList.add('compte')}else{const bar=app.querySelector('.auto-bar');if(bar){bar.classList.remove('run');void bar.offsetWidth;bar.style.setProperty('--d',ms+'ms');bar.classList.add('run')}}const page=pageName;autoT=setTimeout(()=>{if(pageName!==page)return;const b=app.querySelector(`[data-action="${action}"]`);if(b&&!b.disabled)b.click();else if(routes[action])go(action)},ms)}
/* 07/10 (Charles) : sur les questions facultatives, le choix que font la plupart des gens se remplit
   tout seul en 2 s puis passe a la suite ; le moindre geste l'arrete. Jamais sur la question sante. */
let defT=null;function stopDefaut(){clearTimeout(defT);defT=null;app.querySelectorAll('.defaut').forEach(x=>x.classList.remove('defaut'))}
function defaut(p){stopDefaut();if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;let b=null,suite=null;if(p==='besoin'){if((prefs.besoins||[]).length)return;b=app.querySelector('[data-action="besoinAny"]')}else if(p==='types'){if((prefs.types||[]).length)return;b=app.querySelector('[data-action="typesAny"]')}else if(p==='preference'){if(prefs.usage||prefs.bio)return;b=app.querySelector('[data-usage=""]');suite=app.querySelector('[data-action="suitePref"]')}if(!b)return;b.classList.add('defaut');const page=pageName;defT=setTimeout(()=>{if(pageName!==page||!b.isConnected||!b.classList.contains('defaut'))return;b.classList.remove('defaut');(suite||b).click()},2900);['pointerdown','keydown','wheel','touchstart'].forEach(e=>document.addEventListener(e,stopDefaut,{once:true,capture:true}))}
function autoBar(){return '<div class="auto-bar" aria-hidden="true"><i></i></div>'}
function etapes(){return ((s._cases&&s._cases.allergie)?6:5)-(s.rien?1:0)}
function dots(step,n=4){return `<div class="progress" aria-label="Étape ${step} sur ${n}">${Array.from({length:n},(_,i)=>`<i class="${i===step-1?'on':''}" aria-hidden="true"></i>`).join('')}<span>${step} / ${n}</span></div>`}
function bindCore(){Core.state(mode==='normal'?s:null,mode||'normal',prefs,removed,ry)}
function validBase(){return s.rien||!!(s._cases.allergie||s.grossesse||s.anticoagulant||s.reins||(s._cases.regime&&s.regime))}
function validQuestion(){if(s._cases.regime&&!s.regime)return false;return validBase()}
function syncScores(sc,isDemo=false){scores=sc;demo=isDemo;window.__vyScores=sc;bindCore();try{sessionStorage&&typeof sauveSession==='function'&&sauveSession()}catch(e){}}
function sauveSession(){try{sessionStorage.setItem('vy-parcours',JSON.stringify({s,prefs,mode,scores,removed,ry}))}catch(e){}}
function reprendSession(){try{const j=JSON.parse(sessionStorage.getItem('vy-parcours')||'null');if(!j)return false;s=j.s||s;prefs=Object.assign(prefs,j.prefs||{});mode=j.mode||mode;removed=j.removed||[];ry=j.ry||ry;if(j.scores)syncScores(j.scores,false);return true}catch(e){return false}}
function go(name,replace=false){sauveSession();cleanup();cleanup=()=>{};pageName=name;history[replace?'replaceState':'pushState']({page:name},'',routes[name]);render();window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('popstate',()=>{cleanup();pageName=Object.entries(routes).find(([,v])=>location.pathname.endsWith(v))?.[0]||'questions';render()});
function shortDisclaimer(){return `<div class="notice">${esc(TEXT.info)}</div>`}
function globalChrome(){document.getElementById('brand').textContent=TEXT.brand;document.getElementById('navFood').textContent=TEXT.food;document.getElementById('navGallery').textContent=TEXT.gallery;document.getElementById('creditButton').textContent=TEXT.credits;document.getElementById('footerLabel').textContent=TEXT.food}
function computeRemaining(){const prevMode=mode;Core.state(s,'normal',prefs,removed,ry);const ex=Core.exclusions().x,n=Core.get().data.filter(f=>!ex[f.id]).length;bindCore();return n}
function review(){return `<div class="dictation">${esc(Core.phrase(validBase()?s:null))}</div><div class="overline">${computeRemaining()} aliments possibles sur ${Core.get().data.length}</div>`}
function questions(){const notices=[s.grossesse?TEXT.pregnancy:'',s.anticoagulant?TEXT.anticoagulant:'',s.reins?TEXT.kidney:'',s.regime==='vegan'?TEXT.vegan:''].filter(Boolean);app.innerHTML=`<main class="solo"><section class="question-copy"><div class="overline">${TEXT.beforePlate}</div><h1>${esc(TEXT.avoid)}</h1><p>${esc(TEXT.avoidLead)}</p><div class="choices">${TEXT.cases.map(([id,t,sub])=>`<button class="choice ${!s.rien&&(s._cases[id]||s[id])?'selected':''}" data-case="${id}" aria-pressed="${!!(!s.rien&&(s._cases[id]||s[id]))}">${esc(t)}${sub?`<small>${esc(sub)}</small>`:''}</button>`).join('')}</div>${s._cases.regime?`<div class="choices">${[['vegetarien','Végétarien'],['vegan','Végan']].map(([id,t])=>`<button class="choice ${s.regime===id?'selected':''}" data-regime="${id}" aria-pressed="${s.regime===id}">${t}</button>`).join('')}</div>`:''}<button class="nothing ${s.rien?'selected':''}" data-action="nothing"><strong>${TEXT.nothing}</strong><small>${TEXT.nothingNote}</small></button>${notices.map(t=>`<div class="help">${esc(t)}</div>`).join('')}${s._cases.regime&&!s.regime?`<p class="help">${TEXT.regimeHelp}</p>`:''}${review()}${autoBar()}<div class="pied"><div class="links">${button(TEXT.next,'questionNext','text-button',!validQuestion())}</div>${dots(1,etapes())}</div></section>${visual('grenade')}</main>`}
function allergies(){const c=Core.get();let options=Core.allergens.map(([id,t])=>[id,id==='autre'?TEXT.other:t]);app.innerHTML=`<main class="allergy-layout"><section><div class="overline">${TEXT.yourAllergies}</div><h1>${esc(TEXT.allergTitle)}</h1><p>${esc(TEXT.allergLead)}</p>${visual('kiwi')}</section><section><div class="choices">${options.map(([id,t])=>`<button class="choice ${(id==='autre'?s._autre:s.allergies.includes(id))?'selected':''}" data-allergen="${id}" aria-pressed="${!!(id==='autre'?s._autre:s.allergies.includes(id))}">${esc(t)}</button>`).join('')}</div>${s._autre?`<h3>${TEXT.otherTitle}</h3><p class="fine">${TEXT.otherHelp}</p><div class="choices other-list">${c.data.filter(f=>!(f.allergenes_UE||[]).length&&!['pamplemousse','huitre','tofu','noix_bresil'].includes(f.id)).map(f=>`<button class="choice ${s.autres_aliments.includes(f.id)?'selected':''}" data-other="${f.id}" aria-pressed="${s.autres_aliments.includes(f.id)}">${esc(f.nom.split(' (')[0])}</button>`).join('')}</div>`:''}<p class="help">${s.allergies.length||s.autres_aliments.length?TEXT.allergChange:TEXT.allergHint}</p>${review()}<div class="pied"><div class="frame-actions">${button(TEXT.back,'questions','secondary')}${button(TEXT.next,'allergyNext','primary',!(s.allergies.length||s.autres_aliments.length)||(s._autre&&!s.autres_aliments.length))}</div>${dots(2,etapes())}</div></section></main>`}
function prechauffe(){if(prechauffe.fait)return;prechauffe.fait=1;setTimeout(()=>{models().catch(()=>{});Core.catalogue&&Core.catalogue();window.vyCartoPrechauffe&&window.vyCartoPrechauffe()},400)}
function besoin(){prechauffe();const b=prefs.besoins||[];app.innerHTML=`<main class="solo preference"><section class="question-copy"><div class="overline">${TEXT.optional}</div><h1>${esc(TEXT.besoinTitle)}</h1><p>${TEXT.besoinLead}</p><div class="choices">${TEXT.besoins.map(([id,t])=>`<button class="choice ${b.includes(id)?'selected':''}" data-besoin="${id}" aria-pressed="${b.includes(id)}">${t}</button>`).join('')}</div><button class="nothing" data-action="besoinAny"><strong>${TEXT.besoinAny}</strong></button>${autoBar()}<div class="pied"><div class="links">${button(TEXT.back,s._cases.allergie?'allergies':'questions','text-button')}${button(TEXT.next,'types','text-button')}</div>${dots(s._cases.allergie?3:2,etapes())}</div></section>${visual('citron')}</main>`}
function envies(){prechauffe();const t=prefs.types||[];app.innerHTML=`<main class="solo preference"><section class="question-copy"><div class="overline">${TEXT.optional}</div><h1>${esc(TEXT.typesTitle)}</h1><p>${TEXT.typesLead}</p><div class="choices">${TEXT.types.map(([id,x])=>`<button class="choice ${t.includes(id)?'selected':''}" data-type="${id}" aria-pressed="${t.includes(id)}">${x}</button>`).join('')}</div><button class="nothing" data-action="typesAny"><strong>${TEXT.typesAny}</strong></button>${autoBar()}<div class="pied"><div class="links">${button(TEXT.back,'besoin','text-button')}${button(TEXT.next,'preference','text-button')}</div>${dots(s._cases.allergie?4:3,etapes())}</div></section>${visual(t.includes('epices')?'curcuma':t.includes('boissons')?'the_vert':t.includes('legumes')?'brocoli':'fraise')}</main>`}
